import backtrader as bt


class SwingTradingWithRSIFilter(bt.Strategy):
    params = (
        ('sma_period', 50),
        ('rsi_period', 14),
        ('high_lookback', 20),
    )

    def __init__(self):
        self.sma = bt.indicators.SMA(self.data.close, period=self.p.sma_period)
        self.rsi = bt.indicators.RSI(self.data.close, period=self.p.rsi_period)
        self.previous_high = bt.indicators.Highest(
            self.data.high(-1), period=self.p.high_lookback
        )
        self.order = None
        self.target_price = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.data.close[0] > self.sma[0] and self.rsi[0] < 50:
                self.target_price = self.previous_high[0]
                size = (self.broker.getvalue() * 0.01) / self.data.close[0]
                self.order = self.buy(size=size)

    def notify_order(self, order):
        if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
            if order.status == order.Completed and order.isbuy():
                self.order = self.sell(exectype=bt.Order.Limit, price=self.target_price)
            else:
                self.order = None
